/* @autogenerated */
package net.civeira.phylax.bootstrap.telemetry.collector;

import com.fasterxml.jackson.databind.ObjectMapper;

import io.opentelemetry.sdk.logs.export.LogRecordExporter;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Instance;
import jakarta.ws.rs.Consumes;
import jakarta.ws.rs.POST;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.Produces;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;

@Path("/v1/logs")
@Consumes(MediaType.APPLICATION_JSON)
@Produces(MediaType.APPLICATION_JSON)
@ApplicationScoped
@RequiredArgsConstructor
public class OtlpLogsResource {

  private final LogsMapper logsMapper;

  private final Instance<LogRecordExporter> logExporter;

  @POST
  public Response ingestLogs(OtlpLogsRequest request) {
    var logs = logsMapper.toLogRecords(request);
    var success = false;
    for (var exporter : logExporter) {
      var result = exporter.export(logs);
      success |= result.isSuccess();
    }
    return success ? Response.accepted().entity(OtlpSuccessResponse.ok()).build()
        : Response.serverError().entity(OtlpSuccessResponse.partial("log_export_failed")).build();
  }

  /**
   * The same request as text/plain: {@code navigator.sendBeacon} (used by the front when the page
   * is closed) cannot send JSON to another origin without a CORS preflight. The ingest key then
   * comes in {@code ?key=}.
   */
  @POST
  @Consumes(MediaType.TEXT_PLAIN)
  public Response ingestLogsText(final String body) throws java.io.IOException {
    return ingestLogs(JSON.readValue(body, OtlpLogsRequest.class));
  }

  private static final ObjectMapper JSON = new ObjectMapper().configure(
      com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
}
